USE LP2_TelcoChurn;
GO

IF OBJECT_ID('dbo.telco_churn', 'U') IS NOT NULL DROP TABLE dbo.telco_churn;
CREATE TABLE dbo.telco_churn
(
    customer_id          NVARCHAR(20) NULL,
    gender               NVARCHAR(10) NULL,
    senior_citizen       BIT          NULL,
    partner              NVARCHAR(10) NULL,
    dependents           NVARCHAR(10) NULL,
    tenure               TINYINT      NULL,
    phone_service        NVARCHAR(10) NULL,
    multiple_lines       NVARCHAR(20) NULL,
    internet_service     NVARCHAR(20) NULL,
    online_security      NVARCHAR(20) NULL,
    online_backup        NVARCHAR(20) NULL,
    device_protection    NVARCHAR(20) NULL,
    tech_support         NVARCHAR(20) NULL,
    streaming_tv         NVARCHAR(20) NULL,
    streaming_movies     NVARCHAR(20) NULL,
    contract             NVARCHAR(25) NULL,
    paperless_billing    NVARCHAR(10) NULL,
    payment_method       NVARCHAR(30) NULL,
    monthly_charges      FLOAT        NULL,
    total_charges        FLOAT        NULL,
    churn                NVARCHAR(5)  NULL,
    churned              TINYINT      NULL,
    tenure_group         NVARCHAR(10) NULL,
    loaded_at           DATETIME2    NOT NULL CONSTRAINT DF_loaded DEFAULT SYSUTCDATETIME()
);
GO

