-- Indexes
CREATE INDEX IX_telco_churn_gender ON dbo.telco_churn (gender);
CREATE INDEX IX_telco_churn_tenure ON dbo.telco_churn (tenure);
CREATE INDEX IX_telco_churn_internet_service ON dbo.telco_churn (internet_service);
CREATE INDEX IX_telco_churn_contract ON dbo.telco_churn (contract);
CREATE INDEX IX_telco_churn_payment_method ON dbo.telco_churn (payment_method);
CREATE INDEX IX_telco_churn_tenure_group ON dbo.telco_churn (tenure_group);
GO

-- ============ ANALYTICAL VIEWS ============

-- Churn rate by contract type
CREATE OR ALTER VIEW dbo.v_churn_by_contract AS
SELECT contract,
       COUNT(*)                                        AS customers,
       SUM(CAST(churned AS INT))                       AS churned_customers,
       ROUND(100.0 * SUM(CAST(churned AS INT)) / COUNT(*), 1) AS churn_rate_pct,
       ROUND(AVG(monthly_charges), 2)                  AS avg_monthly_charges
FROM dbo.telco_churn
GROUP BY contract;;
GO

-- Churn rate by payment method
CREATE OR ALTER VIEW dbo.v_churn_by_payment AS
SELECT payment_method,
       COUNT(*)                                        AS customers,
       SUM(CAST(churned AS INT))                       AS churned_customers,
       ROUND(100.0 * SUM(CAST(churned AS INT)) / COUNT(*), 1) AS churn_rate_pct,
       ROUND(AVG(monthly_charges), 2)                  AS avg_monthly_charges
FROM dbo.telco_churn
GROUP BY payment_method;;
GO

-- Churn rate by tenure group
CREATE OR ALTER VIEW dbo.v_churn_by_tenure_group AS
SELECT tenure_group,
       COUNT(*)                                        AS customers,
       SUM(CAST(churned AS INT))                       AS churned_customers,
       ROUND(100.0 * SUM(CAST(churned AS INT)) / COUNT(*), 1) AS churn_rate_pct,
       ROUND(AVG(monthly_charges), 2)                  AS avg_monthly_charges
FROM dbo.telco_churn
GROUP BY tenure_group;;
GO

-- Churn rate by internet service
CREATE OR ALTER VIEW dbo.v_churn_by_internet AS
SELECT internet_service,
       COUNT(*)                                        AS customers,
       SUM(CAST(churned AS INT))                       AS churned_customers,
       ROUND(100.0 * SUM(CAST(churned AS INT)) / COUNT(*), 1) AS churn_rate_pct,
       ROUND(AVG(monthly_charges), 2)                  AS avg_monthly_charges
FROM dbo.telco_churn
GROUP BY internet_service;;
GO

-- Churn rate by senior citizen / partner / dependents
CREATE OR ALTER VIEW dbo.v_senior_dependents AS
SELECT senior_citizen, partner, dependents,
       COUNT(*) AS customers,
       SUM(CAST(churned AS INT)) AS churned_customers,
       ROUND(100.0 * SUM(CAST(churned AS INT)) / COUNT(*), 1) AS churn_rate_pct
FROM dbo.telco_churn
GROUP BY senior_citizen, partner, dependents;;
GO

-- Monthly revenue lost to churn
CREATE OR ALTER VIEW dbo.v_revenue_at_risk AS
SELECT contract,
       SUM(CASE WHEN churned = 1 THEN monthly_charges ELSE 0 END) AS lost_monthly_revenue,
       SUM(monthly_charges)                                      AS total_monthly_revenue,
       ROUND(100.0 * SUM(CASE WHEN churned = 1 THEN monthly_charges ELSE 0 END)
             / SUM(monthly_charges), 1)                          AS revenue_at_risk_pct
FROM dbo.telco_churn
GROUP BY contract;;
GO